import React from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";
import { dividerClasses } from "@mui/material";

function GroupNavBar() {
  return (
    <div className="bg-white container">
      <div
        id="group-bar"
        className="bg-white rounded-3 d-flex p-3 justify-content-between mb-4 mt-2 container"
      >
        <h4 className="fw-semibold">Groups management</h4>
        <button className="btn btn-primary btn-sm">Create New Group</button>
      </div>
    </div>
  );
}

export default GroupNavBar;
